/**
 * PROD-029 — the Layer-3 SUBSTITUTION BENCHMARK CHECK RUNNER (the
 * tools/building-benchmark convention: the competitive-parity discipline).
 *
 * Wired into the root `bun run verify` via `benchmark.test.ts` (a tools/
 * test picked up by the root `bun test`).
 *
 * The boundary matrix forbids tools → packages imports, so this runner
 * consumes the COMMITTED ARTIFACTS AS DATA — the committed scenario matrix
 * (`tools/solution-eval/scenario.json`) and the committed golden outcomes
 * (`fixtures/expected-outcomes.json`, regenerated by the backend-side
 * testkit where the harness and the canonical components CAN be imported).
 * The LIVE regeneration check (the freshly computed matrix equals the
 * committed fixture byte-for-byte) lives in the backend-side golden tests
 * for the same boundary reason.
 *
 * What this runner proves over the committed data:
 *
 *  1. the CANONICAL FORM — both artifacts re-serialize byte-identically
 *     (recursively sorted keys, 2-space indent, trailing newline — the
 *     generic canonical-JSON discipline);
 *  2. the MATRIX COMPLETENESS — 4 seams × {equal, divergent} = 8 scenarios,
 *     unique ids, closed vocabularies, lawful seam/baseline/capability
 *     pairings, declared runs answering every input;
 *  3. the DAY-26 GATE (equal substitutions proven) — every
 *     canonical-equality cell is verdict substitution-proven with ZERO
 *     divergent comparison points;
 *  4. the DAY-27 GATE (divergent substitutions CAUGHT) — every
 *     declared-divergence cell is verdict divergence-recorded, carries ≥1
 *     divergent point and records EXACTLY the failure kind its scenario
 *     declared, from the CLOSED vocabulary — a harness that only proves
 *     the happy path is a failed delivery;
 *  5. the CONTROL-PLANE COHERENCE — every cell's benchmark record id and
 *     manifest id are 64-hex canonical digests, and the registry event
 *     count equals inputs + 2 (execution-normalized per input +
 *     benchmark-recorded + provenance-sealed);
 *  6. the EXPECTATION GATE — every cell satisfies its scenario's declared
 *     expectation (the benchmark's own assertion, as data).
 *
 * Determinism: pure reads of committed files + pure arithmetic; no clock,
 * no randomness, no network, no package imports.
 */

import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { resolve } from "node:path";

const SCENARIO_PATH = resolve(import.meta.dir, "scenario.json");
const OUTCOMES_PATH = resolve(import.meta.dir, "fixtures", "expected-outcomes.json");

/* ------------------------------------------------------------------ */
/* The canonical form (the generic discipline — no package imports)      */
/* ------------------------------------------------------------------ */

/** Sort one parsed JSON value's object keys recursively (arrays keep order). */
function sortValue(value: unknown): unknown {
  if (Array.isArray(value)) {
    return value.map(sortValue);
  }
  if (value !== null && typeof value === "object") {
    const record = value as Record<string, unknown>;
    const out: Record<string, unknown> = {};
    for (const key of Object.keys(record).sort()) {
      out[key] = sortValue(record[key]);
    }
    return out;
  }
  return value;
}

/** Canonical JSON text: 2-space indented, sorted keys, trailing newline. */
export function canonicalJson(value: unknown): string {
  return `${JSON.stringify(sortValue(value), null, 2)}\n`;
}

export function sha256Hex(text: string): string {
  return createHash("sha256").update(text, "utf8").digest("hex");
}

/* ------------------------------------------------------------------ */
/* The committed artifacts (typed structural views)                       */
/* ------------------------------------------------------------------ */

export interface ScenarioView {
  readonly scenarioId: string;
  readonly seam: string;
  readonly baselineId: string;
  readonly title: string;
  readonly substitute: {
    readonly providerId: string;
    readonly technologyVersion: string;
  };
  readonly substitutedRun: {
    readonly capability: string;
    readonly executions: readonly {
      readonly inputKey: string;
      readonly execution: unknown;
    }[];
  };
  readonly expectation: string;
  readonly expectedDivergenceKind?: string;
}

export interface ScenarioMatrixView {
  readonly matrixId: string;
  readonly version: string;
  readonly scenarios: readonly ScenarioView[];
  readonly seams: readonly {
    readonly seam: string;
    readonly capability: string;
    readonly baselineId: string;
    readonly canonicalComponent: string;
  }[];
}

export interface OutcomeCellView {
  readonly scenarioId: string;
  readonly seam: string;
  readonly expectation: string;
  readonly verdict: string;
  readonly expectationSatisfied: boolean;
  readonly comparisonPointCount: number;
  readonly equalPointCount: number;
  readonly divergentPointCount: number;
  readonly divergenceFailureKind?: string;
  readonly refusalKind?: string;
  readonly benchmarkRecordId?: string;
  readonly benchmarkRecordDigest?: string;
  readonly manifestId?: string;
  readonly registryEventCount: number;
  readonly points: readonly {
    readonly pointKind: string;
    readonly subjectId: string;
    readonly equal: boolean;
  }[];
}

export interface ExpectedOutcomesView {
  readonly matrixId: string;
  readonly totals: {
    readonly scenarios: number;
    readonly proven: number;
    readonly divergenceRecorded: number;
    readonly refused: number;
    readonly expectationSatisfied: number;
  };
  readonly cells: readonly OutcomeCellView[];
}

function asRecord(value: unknown, label: string): Record<string, unknown> {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    throw new Error(`${label}: expected a JSON object`);
  }
  return value as Record<string, unknown>;
}

function requireString(record: Record<string, unknown>, field: string): string {
  const value = record[field];
  if (typeof value !== "string" || value.length === 0) {
    throw new Error(`the '${field}' field must be a non-empty string`);
  }
  return value;
}

/** Loads and structurally views the committed scenario matrix. */
export function loadScenarioMatrix(): ScenarioMatrixView {
  const document = JSON.parse(readFileSync(SCENARIO_PATH, "utf8")) as unknown;
  const record = asRecord(document, "scenario.json");
  const seams = record["seams"] as unknown;
  const scenarios = record["scenarios"] as unknown;
  if (!Array.isArray(seams) || !Array.isArray(scenarios)) {
    throw new Error("scenario.json: 'seams' and 'scenarios' must be arrays");
  }
  return {
    matrixId: requireString(record, "matrixId"),
    version: requireString(record, "version"),
    seams: seams as ScenarioMatrixView["seams"],
    scenarios: scenarios as ScenarioMatrixView["scenarios"],
  };
}

/** Loads and structurally views the committed expected outcomes. */
export function loadExpectedOutcomes(): ExpectedOutcomesView {
  const document = JSON.parse(readFileSync(OUTCOMES_PATH, "utf8")) as unknown;
  const record = asRecord(document, "expected-outcomes.json");
  const totals = asRecord(record["totals"], "totals");
  const cells = record["cells"] as unknown;
  if (!Array.isArray(cells)) {
    throw new Error("expected-outcomes.json: 'cells' must be an array");
  }
  return {
    matrixId: requireString(record, "matrixId"),
    totals: {
      scenarios: totals["scenarios"] as number,
      proven: totals["proven"] as number,
      divergenceRecorded: totals["divergenceRecorded"] as number,
      refused: totals["refused"] as number,
      expectationSatisfied: totals["expectationSatisfied"] as number,
    },
    cells: cells as ExpectedOutcomesView["cells"],
  };
}

/* ------------------------------------------------------------------ */
/* The closed vocabularies (stated independently in this runner)          */
/* ------------------------------------------------------------------ */

export const SEAMS = ["operation-compiler", "engine-execution", "validation", "boq-derivation"] as const;
export const SEAM_CAPABILITY: Record<string, string> = {
  "operation-compiler": "layer3-operation-compiler",
  "engine-execution": "layer3-engine-execution",
  validation: "layer3-validation",
  "boq-derivation": "layer3-boq-derivation",
};
export const FAILURE_KINDS = [
  "perception-failure",
  "retrieval-failure",
  "reasoning-failure",
  "unsupported-data",
  "operation-semantic-failure",
  "resource-exhaustion",
  "timeout",
  "license-blocked",
  "contract-mismatch",
] as const;
/** The divergence taxonomy (the harness's frozen mapping, restated independently). */
export const DIVERGENCE_KIND_BY_POINT: Record<string, string> = {
  "operation-identity": "operation-semantic-failure",
  "state-digest": "operation-semantic-failure",
  "quantity-value": "operation-semantic-failure",
  "validation-verdict": "reasoning-failure",
  "boq-line": "operation-semantic-failure",
};
export const POINT_KINDS = [
  "operation-identity",
  "state-digest",
  "quantity-value",
  "validation-verdict",
  "boq-line",
] as const;

/** The committed matrix's per-seam reference counts (independently restated). */
export const SEAM_POINT_COUNTS: Record<string, number> = {
  "operation-compiler": 3,
  "engine-execution": 10,
  validation: 8,
  "boq-derivation": 7,
};

/* ------------------------------------------------------------------ */
/* The checks (pure functions; every violation is a typed finding)        */
/* ------------------------------------------------------------------ */

export interface Finding {
  readonly check: string;
  readonly detail: string;
}

/** 1. The canonical-form check: the committed files ARE canonical JSON. */
export function checkCanonicalForm(): readonly Finding[] {
  const findings: Finding[] = [];
  for (const [label, path] of [
    ["scenario.json", SCENARIO_PATH],
    ["fixtures/expected-outcomes.json", OUTCOMES_PATH],
  ] as const) {
    const text = readFileSync(path, "utf8");
    const parsed = JSON.parse(text) as unknown;
    if (canonicalJson(parsed) !== text) {
      findings.push({
        check: "canonical-form",
        detail: `${label} is not in canonical form (recursively sorted keys, 2-space indent, trailing newline)`,
      });
    }
  }
  return findings;
}

/** 2. The matrix-completeness check. */
export function checkMatrixCompleteness(matrix: ScenarioMatrixView): readonly Finding[] {
  const findings: Finding[] = [];
  if (matrix.matrixId !== "layer3-substitution-matrix/1") {
    findings.push({ check: "matrix-id", detail: `unexpected matrixId '${matrix.matrixId}'` });
  }
  if (matrix.scenarios.length !== 8) {
    findings.push({
      check: "matrix-completeness",
      detail: `expected 4 seams × 2 scenarios = 8, found ${matrix.scenarios.length}`,
    });
  }
  const ids = new Set<string>();
  for (const scenario of matrix.scenarios) {
    if (ids.has(scenario.scenarioId)) {
      findings.push({
        check: "unique-scenario-ids",
        detail: `duplicate scenarioId '${scenario.scenarioId}'`,
      });
    }
    ids.add(scenario.scenarioId);
    if (!(SEAMS as readonly string[]).includes(scenario.seam)) {
      findings.push({
        check: "closed-seam-vocabulary",
        detail: `scenario '${scenario.scenarioId}': unknown seam '${scenario.seam}'`,
      });
      continue;
    }
    if (SEAM_CAPABILITY[scenario.seam] !== scenario.substitutedRun.capability) {
      findings.push({
        check: "seam-capability-pairing",
        detail: `scenario '${scenario.scenarioId}': capability '${scenario.substitutedRun.capability}' does not name seam '${scenario.seam}'`,
      });
    }
    if (scenario.substitutedRun.executions.length === 0) {
      findings.push({
        check: "declared-run-nonempty",
        detail: `scenario '${scenario.scenarioId}': the declared run answers no input`,
      });
    }
    if (
      scenario.expectation === "declared-divergence" &&
      !(FAILURE_KINDS as readonly string[]).includes(scenario.expectedDivergenceKind ?? "")
    ) {
      findings.push({
        check: "declared-failure-kind",
        detail: `scenario '${scenario.scenarioId}': expectedDivergenceKind '${String(scenario.expectedDivergenceKind)}' is not in the CLOSED failure vocabulary`,
      });
    }
  }
  for (const seam of SEAMS) {
    const seamScenarios = matrix.scenarios.filter((scenario) => scenario.seam === seam);
    const equal = seamScenarios.filter((s) => s.expectation === "canonical-equality");
    const divergent = seamScenarios.filter((s) => s.expectation === "declared-divergence");
    if (equal.length !== 1 || divergent.length !== 1) {
      findings.push({
        check: "matrix-completeness",
        detail: `seam '${seam}': expected exactly one equal and one divergent scenario (found ${equal.length}/${divergent.length})`,
      });
    }
  }
  return findings;
}

/** 3+4+5+6. The outcome checks (the day-26/27 gates + control-plane coherence). */
export function checkOutcomes(
  matrix: ScenarioMatrixView,
  outcomes: ExpectedOutcomesView,
): readonly Finding[] {
  const findings: Finding[] = [];
  if (outcomes.matrixId !== matrix.matrixId) {
    findings.push({
      check: "matrix-id-pairing",
      detail: "the scenario matrix and the expected outcomes name different matrix ids",
    });
  }
  const byId = new Map(outcomes.cells.map((cell) => [cell.scenarioId, cell]));
  for (const scenario of matrix.scenarios) {
    const cell = byId.get(scenario.scenarioId);
    if (cell === undefined) {
      findings.push({
        check: "cell-pairing",
        detail: `scenario '${scenario.scenarioId}' has no outcome cell`,
      });
      continue;
    }
    if (cell.seam !== scenario.seam) {
      findings.push({
        check: "cell-seam-pairing",
        detail: `cell '${cell.scenarioId}': seam mismatch (${cell.seam} vs ${scenario.seam})`,
      });
    }
    if (!cell.expectationSatisfied) {
      findings.push({
        check: "expectation-gate",
        detail: `cell '${cell.scenarioId}': the harness verdict CONTRADICTS the declared expectation`,
      });
    }
    if (cell.comparisonPointCount !== SEAM_POINT_COUNTS[scenario.seam]) {
      findings.push({
        check: "comparison-point-count",
        detail: `cell '${cell.scenarioId}': expected ${SEAM_POINT_COUNTS[scenario.seam]} comparison points for the '${scenario.seam}' seam, found ${cell.comparisonPointCount}`,
      });
    }
    if (cell.points.length !== cell.comparisonPointCount) {
      findings.push({
        check: "point-projection",
        detail: `cell '${cell.scenarioId}': the per-point projection count does not match comparisonPointCount`,
      });
    }
    for (const point of cell.points) {
      if (!(POINT_KINDS as readonly string[]).includes(point.pointKind)) {
        findings.push({
          check: "closed-point-vocabulary",
          detail: `cell '${cell.scenarioId}': unknown comparison point kind '${point.pointKind}'`,
        });
      }
    }

    if (scenario.expectation === "canonical-equality") {
      /* The day-26 gate: the equal substitution is PROVEN. */
      if (cell.verdict !== "substitution-proven") {
        findings.push({
          check: "day26-equal-proven",
          detail: `cell '${cell.scenarioId}': an equal scenario must be proven, got '${cell.verdict}'`,
        });
      }
      if (cell.divergentPointCount !== 0) {
        findings.push({
          check: "day26-equal-proven",
          detail: `cell '${cell.scenarioId}': a proven substitution has zero divergent points, found ${cell.divergentPointCount}`,
        });
      }
      if (cell.points.some((point) => !point.equal)) {
        findings.push({
          check: "day26-equal-proven",
          detail: `cell '${cell.scenarioId}': a proven substitution has no unequal point`,
        });
      }
    } else {
      /* The day-27 gate: the divergent substitution is CAUGHT with the right kind. */
      if (cell.verdict !== "divergence-recorded") {
        findings.push({
          check: "day27-divergence-caught",
          detail: `cell '${cell.scenarioId}': a declared divergence must be caught, got '${cell.verdict}'`,
        });
      }
      if (cell.divergentPointCount < 1) {
        findings.push({
          check: "day27-divergence-caught",
          detail: `cell '${cell.scenarioId}': a caught divergence carries at least one divergent point`,
        });
      }
      const declared = scenario.expectedDivergenceKind ?? "(undeclared)";
      if (cell.divergenceFailureKind !== declared) {
        findings.push({
          check: "day27-failure-kind",
          detail: `cell '${cell.scenarioId}': the recorded failure kind '${String(cell.divergenceFailureKind)}' does not match the declared '${declared}'`,
        });
      }
      if (!(FAILURE_KINDS as readonly string[]).includes(cell.divergenceFailureKind ?? "")) {
        findings.push({
          check: "day27-failure-kind",
          detail: `cell '${cell.scenarioId}': the recorded failure kind is not in the CLOSED vocabulary`,
        });
      }
    }

    /* Control-plane coherence. */
    if (cell.benchmarkRecordId === undefined || !/^[0-9a-f]{64}$/.test(cell.benchmarkRecordId)) {
      findings.push({
        check: "record-id",
        detail: `cell '${cell.scenarioId}': the benchmark record id must be a 64-hex canonical digest`,
      });
    }
    if (cell.manifestId === undefined || !/^[0-9a-f]{64}$/.test(cell.manifestId)) {
      findings.push({
        check: "manifest-id",
        detail: `cell '${cell.scenarioId}': the provenance manifest id must be a 64-hex canonical digest`,
      });
    }
    const expectedEventCount = scenario.substitutedRun.executions.length + 2;
    if (cell.registryEventCount !== expectedEventCount) {
      findings.push({
        check: "registry-event-count",
        detail: `cell '${cell.scenarioId}': expected ${expectedEventCount} registry events (inputs + benchmark-recorded + provenance-sealed), found ${cell.registryEventCount}`,
      });
    }
  }
  if (byId.size !== matrix.scenarios.length) {
    findings.push({
      check: "cell-pairing",
      detail: `the outcomes carry ${byId.size} cells for ${matrix.scenarios.length} scenarios`,
    });
  }

  /* Totals coherence. */
  const totals = outcomes.totals;
  if (totals.scenarios !== matrix.scenarios.length) {
    findings.push({ check: "totals", detail: "totals.scenarios does not match the matrix" });
  }
  const proven = outcomes.cells.filter((cell) => cell.verdict === "substitution-proven").length;
  const divergenceRecorded = outcomes.cells.filter(
    (cell) => cell.verdict === "divergence-recorded",
  ).length;
  const refused = outcomes.cells.filter((cell) => cell.verdict === "substitution-refused").length;
  if (totals.proven !== proven || totals.divergenceRecorded !== divergenceRecorded || totals.refused !== refused) {
    findings.push({ check: "totals", detail: "the totals do not match the cells' verdicts" });
  }
  if (totals.refused !== 0) {
    findings.push({
      check: "totals",
      detail: `the committed matrix has no refused cell, found ${totals.refused}`,
    });
  }
  if (totals.expectationSatisfied !== matrix.scenarios.length) {
    findings.push({
      check: "totals",
      detail: "every committed cell must satisfy its declared expectation",
    });
  }
  if (proven !== 4 || divergenceRecorded !== 4) {
    findings.push({
      check: "totals",
      detail: `the committed matrix proves 4 and catches 4 (found ${proven}/${divergenceRecorded})`,
    });
  }
  return findings;
}

/** The one-shot runner: every check over the committed artifacts. */
export function runAllChecks(): readonly Finding[] {
  const matrix = loadScenarioMatrix();
  const outcomes = loadExpectedOutcomes();
  return [
    ...checkCanonicalForm(),
    ...checkMatrixCompleteness(matrix),
    ...checkOutcomes(matrix, outcomes),
  ];
}

/** The deterministic digest of the committed outcomes document (stability pin). */
export function outcomesDigest(): string {
  return sha256Hex(readFileSync(OUTCOMES_PATH, "utf8"));
}
